    Returns
    -------
    list of pandas.DataFrame
        The updated datasets, each with the new random column added.

    Raises
    ------
    TypeError
        If `datasets` is not a list, or if any element is not a pandas
        DataFrame.
    """
    if not isinstance(datasets, list):
        raise TypeError("`datasets` must be a list of pandas DataFrames.")

    updated_datasets = []
    for i, dataset in enumerate(datasets):
        if not isinstance(dataset, pd.DataFrame):
            raise TypeError(
                f"Dataset at index {i} is not a pandas DataFrame "
                f"(got {type(dataset).__name__})."
