        # Build a unique column name for this dataset.
        col_name = f"{key_prefix}_{i}"
        while col_name in dataset.columns:
            col_name += "_x"

        # Work on a copy so the original input is not mutated.
        dataset = dataset.copy()
        dataset[col_name] = np.random.uniform(min_value, max_value, size=len(dataset))
        updated_datasets.append(dataset)

    return updated_datasets
